/**
 * Builds a plain HTTP GET request for a signed Rayvn URL.
 * No authentication required — signed URLs are publicly accessible.
 * Mirrors Get Wasos file — Build download request.
 */
const file = msg.payload;

return {
    _msgid:     msg._msgid,
    _dl:        msg._dl,
    parts:      msg.parts,
    metadata:   msg.metadata,
    _file_meta: {
        url:  file.url,
        name: file.name || "attachment",
        type: file.type || "application/octet-stream",
        size: file.size || 0
    },
    url:   file.url,
    topic: msg.topic
};

/**                                                                                                                                                                                              
 * Resolves actual Content-Type and filename from HTTP response headers                                                                                                                          
 * (msg.headers in Node-RED) and writes into _file_meta.                                                                                                                                         
 *                                                                                                                                                                                               
 * Azure blob storage always returns application/octet-stream as Content-Type                                                                                                                    
 * regardless of file type. The filename is derived from Content-Disposition                                                                                                                     
 * first, then from the URL path. When Content-Type is still octet-stream,                                                                                                                       
 * utils.get_mime_type() resolves the correct type from the filename extension.                                                                                                                  
 */
const utils = global.get("utils");
const headers = msg.headers || {};

const raw_ct = headers['content-type'] || msg._file_meta.type;
const actual_type = raw_ct.split(";")[0].trim();

let actual_name = msg._file_meta.name;
const disposition = headers['content-disposition'] || "";
const cd_match = disposition.match(/filename\*?=['"]?(?:UTF-8'')?([^;'"\r\n]+)/i);

if (cd_match) {
    actual_name = decodeURIComponent(cd_match[1].trim());
}

if (actual_type === "application/octet-stream") {
    msg._file_meta.type = utils.get_mime_type(actual_name) || actual_type;
} else {
    msg._file_meta.type = actual_type;
}

msg._file_meta.name = actual_name;

node.log("Resolved: " + actual_name + " (" + msg._file_meta.type + ")");

return msg;
